{
"html": "<div data-ui-unit="E2" class="e2-wrapper">
    <label class="e2-label" for="search">멘토 검색</label>
    <div class="e2-search-surface">
        <svg class="e2-icon" viewBox="0 0 24 24" width="20" height="20">
            <path fill="currentColor" d="M15.5 14h-.79l-.28-.27A6.471 6.471 0 0 0 16 9.5 6.5 6.5 0 1 0 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19l-4.99-5zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14z"/>
        </svg>
        <input type="text" id="search" class="e2-input" placeholder="멘토 또는 회사를 검색하세요" disabled>
    </div>
</div>",
"css": "[data-ui-unit="E2"] {
    width: 100%;
    display: flex;
    flex-direction: column;
}

.e2-label {
    font-size: 14px;
    font-weight: 500;
    color: #283548;
    margin-bottom: 8px;
    line-height: 1.57;
}

.e2-search-surface {
    display: flex;
    align-items: center;
    background-color: #ffffff;
    border-radius: 12px;
    min-height: 46px;
    padding: 0 16px;
    gap: 12px;
}

.e2-icon {
    flex-shrink: 0;
    color: #566273;
    display: block;
}

.e2-input {
    flex: 1;
    min-width: 0;
    border: none;
    background: transparent;
    padding: 0;
    margin: 0;
    color: #283548;
    font-family: inherit;
    font-size: inherit;
    font-weight: inherit;
    line-height: inherit;
}

.e2-input::placeholder {
    color: #566273;
    opacity: 1;
}

@media (prefers-reduced-motion: reduce) {
    [data-ui-unit="E2"] * {
        transition: none !important;
        animation: none !important;
    }
}"
}
